function run(selected_text) {
  const matches = selected_text.match(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi) || [];
  const seen = new Set();
  const emails = [];
  matches.forEach((email) => {
    const key = email.toLowerCase();
    if (!seen.has(key)) {
      seen.add(key);
      emails.push(email);
    }
  });
  return emails.length ? emails.join("\n") : "No email addresses found.";
}
